        CHECK(same_object(opened_a, identity_a));
        CHECK(syscall(SYS_newfstatat, AT_FDCWD, path_a, &path_stat, 0) == 0);
        CHECK(same_object(opened_a, path_stat));
        int alias = dup(low);
